/** Look one up the way a 15-character code presents itself. */
export function lookupLegacy(
  scheme: string,
  dimension: string,
  functionId: string,
): LegacyEntry | undefined {
  return LEGACY_2525C[`${scheme}${dimension}${functionId}`.toUpperCase()];
}
